    r.setTotal(rs.getBigDecimal("total"));
    r.setStatus(Reservation.Status.valueOf(rs.getString("status")));
    r.setAmountPaid(rs.getBigDecimal("amount_paid"));
    r.setRefund(rs.getBigDecimal("refund"));
    return r;
  }
}

