    return csv.toString();
  }

  private String formatDate(LocalDate date) {
    return String.format("%04d-%02d-%02d", date.getYear(), date.getMonthValue(), date.getDayOfMonth());
  }

  private String formatMoney(BigDecimal amount) {
    return String.format("%.2f", amount);
  }
}

